      ro: ["Găzduiește vulturul filipinez și cacaduul filipinez.", "Solul este bogat în metale, ceea ce duce la flora pitică.", "Vârful are o altitudine de 1.620 de metri."],
      en: ["Home to the Philippine eagle and Philippine cockatoo.", "The soil is rich in metals, leading to the pygmy flora.", "The peak has an elevation of 1,620 meters."],
