      hu: ["45 szigetet és szigetecskét foglal magában.", "Több mint 800 halfajnak ad otthont.", "Veszélyeztetett tengeri teknősök fészkelőhelye."],
      ro: ["Include 45 de insule și insulițe.", "Găzduiește peste 800 de specii de pești.", "Loc de cuibărit pentru țestoasele marine pe cale de dispariție."],
      en: ["Encompasses 45 islands and islets.", "Home to over 800 species of fish.", "Nesting site for endangered sea turtles."],
      es: ["Comprende 45 islas e islotes.", "Hogar de más de 800 especies de peces.", "Lugar de anidación para tortugas marinas en peligro de extinción."],
      pt: ["Compreende 45 ilhas e ilhéus.", "Lar de mais de 800 espécies de peixe.", "Local de nidificação para tartarugas marinhas em perigo."],
      fr: ["Comprend 45 îles et îlots.", "Habitat de plus de 800 espèces de poissons.", "Lieu de ponte pour les tortues marines menacées."],
