      ro: "Terase vechi de 2.000 de ani, sculptate în munții din Ifugao de către strămoșii poporului indigen Ifugao.",
      en: "2,000-year-old terraces carved into the mountains of Ifugao by the ancestors of the indigenous Ifugao people.",
      es: "Terrazas de 2.000 años de antigüedad talladas en las montañas de Ifugao por los ancestros de los indígenas Ifugao.",
      pt: "Terraços com 2.000 anos de idade esculpidos nas montanhas de Ifugao pelos antepassados dos indígenas Ifugao.",
