      hu: ["Gyakran a 'világ nyolcadik csodájaként' emlegetik.", "UNESCO Világörökség része.", "Ma is használják rizs és zöldségek termesztésére."],
      ro: ["Adesea denumite 'A opta minune a lumii'.", "Sit al Patrimoniului Mondial UNESCO.", "Sunt încă folosite astăzi pentru cultivarea orezului și legumelor."],
      en: ["Often referred to as the 'Eighth Wonder of the World'.", "A UNESCO World Heritage site.", "Still used today for growing rice and vegetables."],
